$(document).ready(function () {
    const $form = $('#tax-type-form');

    if ($form.length) {
        $form.on('submit', function (e) {
            e.preventDefault();

            const $btn = $('#submit-btn');
            $btn.prop('disabled', true).text('Saving...');

            $.ajax({
                url: $form.attr('action'),
                type: 'POST',
                data: $form.serialize(),
                dataType: 'json',
                success: function (response) {
                    if (response.status === 'success' || response.success == 1) {
                        toastr.success(response.message || 'Tax Type saved successfully');
                        setTimeout(function () {
                            window.location.href = response.redirect;
                        }, 1500);
                    } else {
                        $btn.prop('disabled', false).text('Save Tax Type');
                        if (response.errors) {
                            let errorMsg = '';
                            $.each(response.errors, function (key, value) {
                                errorMsg += value + '<br>';
                            });
                            toastr.error(errorMsg);
                        } else {
                            toastr.error(response.message || 'An error occurred');
                        }
                    }
                },
                error: function () {
                    $btn.prop('disabled', false).text('Save Tax Type');
                    toastr.error('Server error occurred. Please try again.');
                }
            });
        });
    }
});
